-- V1: terrain (TIN) and LandXML import persistence.
-- All lengths/elevations are SI metres (columns end in _m). No DEFAULT values and no value CHECKs on engineering
-- columns: value validation is the job of the domain model (it re-validates on read); the database only stores.
-- TIN vertices/triangles are stored as little-endian binary blobs (see TinBinaryCodec). Do not edit this file once
-- released - add V3+ instead.

CREATE TABLE terrain (
    id                    VARCHAR(36)      NOT NULL,
    project_id            VARCHAR          NOT NULL,
    has_coordinate_system BOOLEAN          NOT NULL,
    crs_epsg_code         VARCHAR,
    crs_name              VARCHAR,
    source_type           VARCHAR,
    source_file_name      VARCHAR,
    bounds_min_x          DOUBLE PRECISION NOT NULL,
    bounds_min_y          DOUBLE PRECISION NOT NULL,
    bounds_min_z          DOUBLE PRECISION NOT NULL,
    bounds_max_x          DOUBLE PRECISION NOT NULL,
    bounds_max_y          DOUBLE PRECISION NOT NULL,
    bounds_max_z          DOUBLE PRECISION NOT NULL,
    min_elevation_m       DOUBLE PRECISION NOT NULL,
    max_elevation_m       DOUBLE PRECISION NOT NULL,
    local_origin_x        DOUBLE PRECISION NOT NULL,
    local_origin_y        DOUBLE PRECISION NOT NULL,
    local_origin_z        DOUBLE PRECISION NOT NULL,
    version               INTEGER          NOT NULL,
    status                VARCHAR(32)      NOT NULL,
    vertex_count          INTEGER          NOT NULL,
    vertices              BYTEA            NOT NULL,
    triangle_count        INTEGER          NOT NULL,
    triangles             BYTEA            NOT NULL,
    row_version           BIGINT           NOT NULL,
    CONSTRAINT pk_terrain PRIMARY KEY (id)
);

-- 0..1 per terrain: no row => TerrainModel.source == null (e.g. an XYZ import).
CREATE TABLE terrain_source (
    terrain_id               VARCHAR(36) NOT NULL,
    application              VARCHAR,
    format_version           VARCHAR,
    units                    VARCHAR,
    surface_name             VARCHAR,
    coordinate_order         VARCHAR,
    source_point_count       INTEGER     NOT NULL,
    source_face_count        INTEGER     NOT NULL,
    invalid_points           INTEGER     NOT NULL,
    duplicate_point_ids      INTEGER     NOT NULL,
    invalid_faces            INTEGER     NOT NULL,
    missing_point_references INTEGER     NOT NULL,
    degenerate_faces         INTEGER     NOT NULL,
    CONSTRAINT pk_terrain_source PRIMARY KEY (terrain_id),
    CONSTRAINT fk_terrain_source_terrain FOREIGN KEY (terrain_id) REFERENCES terrain (id)
);

CREATE TABLE terrain_boundary (
    terrain_id  VARCHAR(36) NOT NULL,
    ordinal     INTEGER     NOT NULL,
    name        VARCHAR,
    type        VARCHAR,
    edge_trim   BOOLEAN     NOT NULL,
    point_count INTEGER     NOT NULL,
    points      BYTEA       NOT NULL,
    CONSTRAINT pk_terrain_boundary PRIMARY KEY (terrain_id, ordinal),
    CONSTRAINT fk_terrain_boundary_terrain FOREIGN KEY (terrain_id) REFERENCES terrain (id)
);

CREATE TABLE terrain_breakline (
    terrain_id  VARCHAR(36) NOT NULL,
    ordinal     INTEGER     NOT NULL,
    name        VARCHAR,
    point_count INTEGER     NOT NULL,
    points      BYTEA       NOT NULL,
    CONSTRAINT pk_terrain_breakline PRIMARY KEY (terrain_id, ordinal),
    CONSTRAINT fk_terrain_breakline_terrain FOREIGN KEY (terrain_id) REFERENCES terrain (id)
);

CREATE TABLE landxml_import (
    id           VARCHAR(36) NOT NULL,
    terrain_id   VARCHAR(36) NOT NULL,
    profile_name VARCHAR,
    CONSTRAINT pk_landxml_import PRIMARY KEY (id),
    CONSTRAINT fk_landxml_import_terrain FOREIGN KEY (terrain_id) REFERENCES terrain (id)
);

CREATE INDEX ix_landxml_import_terrain ON landxml_import (terrain_id);

CREATE TABLE landxml_import_warning (
    import_id VARCHAR(36) NOT NULL,
    ordinal   INTEGER     NOT NULL,
    message   VARCHAR     NOT NULL,
    CONSTRAINT pk_landxml_import_warning PRIMARY KEY (import_id, ordinal),
    CONSTRAINT fk_landxml_warning_import FOREIGN KEY (import_id) REFERENCES landxml_import (id)
);

-- No rows for an import => the import has no alignment (alignment == null).
CREATE TABLE landxml_alignment_element (
    import_id VARCHAR(36)      NOT NULL,
    ordinal   INTEGER          NOT NULL,
    kind      VARCHAR(16)      NOT NULL,
    start_x   DOUBLE PRECISION NOT NULL,
    start_y   DOUBLE PRECISION NOT NULL,
    start_z   DOUBLE PRECISION NOT NULL,
    end_x     DOUBLE PRECISION NOT NULL,
    end_y     DOUBLE PRECISION NOT NULL,
    end_z     DOUBLE PRECISION NOT NULL,
    center_x  DOUBLE PRECISION,
    center_y  DOUBLE PRECISION,
    center_z  DOUBLE PRECISION,
    radius_m  DOUBLE PRECISION,
    clockwise BOOLEAN,
    CONSTRAINT pk_landxml_alignment_element PRIMARY KEY (import_id, ordinal),
    CONSTRAINT fk_landxml_alignment_import FOREIGN KEY (import_id) REFERENCES landxml_import (id),
    CONSTRAINT ck_landxml_alignment_kind CHECK (kind IN ('STRAIGHT', 'CURVE')),
    -- structural only: curve geometry columns are present exactly for CURVE rows
    CONSTRAINT ck_landxml_alignment_curve_cols CHECK (
        (kind = 'CURVE' AND center_x IS NOT NULL AND center_y IS NOT NULL AND center_z IS NOT NULL
            AND radius_m IS NOT NULL AND clockwise IS NOT NULL)
        OR (kind = 'STRAIGHT' AND center_x IS NULL AND center_y IS NULL AND center_z IS NULL
            AND radius_m IS NULL AND clockwise IS NULL))
);

-- No rows for an import => the import has no vertical profile (profile == null).
CREATE TABLE landxml_profile_pvi (
    import_id      VARCHAR(36)      NOT NULL,
    ordinal        INTEGER          NOT NULL,
    chainage_m     DOUBLE PRECISION NOT NULL,
    elevation_m    DOUBLE PRECISION NOT NULL,
    curve_length_m DOUBLE PRECISION NOT NULL,
    CONSTRAINT pk_landxml_profile_pvi PRIMARY KEY (import_id, ordinal),
    CONSTRAINT fk_landxml_pvi_import FOREIGN KEY (import_id) REFERENCES landxml_import (id)
);
